def bucket_by_range(nums, boundaries):
    from collections import Counter
    def bucket_index(x):
        return sum(1 for b in boundaries if b <= x)
    return dict(Counter(bucket_index(x) for x in nums))

def truncate_with_ellipsis(s, max_len):
    if len(s) <= max_len:
        return s
    chars = []
    for i, ch in enumerate(s):
        if i >= max_len - 3:
            break
        chars.append(ch)
    return ''.join(chars) + '...'

