def is_semiprime(n):
    def is_prime(k):
        if k < 2:
            return False
        i = 2
        while i * i <= k:
            if k % i == 0:
                return False
            i += 1
        return True
    if n < 4:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            other = n // i
            if is_prime(i) and is_prime(other):
                return True
        i += 1
    return False

