def recursive_merge_sum_leaves(a, b):
    keys = set(a) | set(b)
    result = {}
    for key in keys:
        if key in a and key not in b:
            result[key] = a[key]
        elif key in b and key not in a:
            result[key] = b[key]
        else:
            av, bv = a[key], b[key]
            if isinstance(av, dict) and isinstance(bv, dict):
                result[key] = recursive_merge_sum_leaves(av, bv)
            elif isinstance(av, (int, float)) and not isinstance(av, bool) and isinstance(bv, (int, float)) and not isinstance(bv, bool):
                result[key] = av + bv
            else:
                result[key] = bv
    return result

