def zip_shortest(a, b):
    result = []
    it_a = iter(a)
    it_b = iter(b)
    while True:
        try:
            x = next(it_a)
            y = next(it_b)
        except StopIteration:
            break
        result.append([x, y])
    return result

def stable_sort_with_original_index(nums):
    order = list(range(len(nums)))
    for i in range(1, len(order)):
        j = i
        while j > 0 and (nums[order[j]], order[j]) < (nums[order[j - 1]], order[j - 1]):
            order[j], order[j - 1] = order[j - 1], order[j]
            j -= 1
    return order

