def top_k_frequent_values(items, k):
    freq = {}
    for x in items:
        freq[x] = freq.get(x, 0) + 1
    buckets = {}
    for value, count in freq.items():
        buckets.setdefault(count, []).append(value)
    result = []
    for count in sorted(buckets.keys(), reverse=True):
        for value in sorted(buckets[count]):
            result.append(value)
    return result[:k]

