def set_nested(d, path, value, sep):
    keys = path.split(sep)
    return _set_nested_helper(d, keys, value)


def _set_nested_helper(d, keys, value):
    key = keys[0]
    rest = keys[1:]
    new_d = dict(d)
    if not rest:
        new_d[key] = value
    else:
        child = new_d.get(key)
        if not isinstance(child, dict):
            child = {}
        new_d[key] = _set_nested_helper(child, rest, value)
    return new_d
